""" Tests for timezone utility functions.
These tests ensure that timezone handling works correctly for PostgreSQL TIMESTAMP WITHOUT TIME ZONE columns. """ import pytest from datetime import datetime import pytz from app.core.timezone import ( strip_timezone, ensure_naive_datetime, prepare_datetime_for_db )
class TestTimezoneUtils: """Test timezone utility functions."""
def test_strip_timezone_with_utc(self): """Test strip_timezone with UTC timezone.""" dt_aware = datetime(2025, 1, 15, 12, 0, 0, tzinfo=pytz.UTC) dt_naive = strip_timezone(dt_aware)
assert dt_naive.tzinfo is None assert dt_naive.year == 2025 assert dt_naive.month == 1 assert dt_naive.day == 15 assert dt_naive.hour == 12 assert dt_naive.minute == 0 assert dt_naive.second == 0
def test_strip_timezone_with_other_timezone(self): """Test strip_timezone with non-UTC timezone.""" est = pytz.timezone('US/Eastern') dt_aware = est.localize(datetime(2025, 1, 15, 12, 0, 0)) dt_naive = strip_timezone(dt_aware)
assert dt_naive.tzinfo is None # Should preserve the datetime values assert dt_naive.year == 2025 assert dt_naive.month == 1 assert dt_naive.day == 15
def test_strip_timezone_with_naive_datetime(self): """Test strip_timezone with already naive datetime.""" dt_naive = datetime(2025, 1, 15, 12, 0, 0) result = strip_timezone(dt_naive)
assert result.tzinfo is None assert result == dt_naive
def test_strip_timezone_with_none(self): """Test strip_timezone with None input.""" result = strip_timezone(None) assert result is None
def test_ensure_naive_datetime_with_utc(self): """Test ensure_naive_datetime with UTC timezone.""" dt_aware = datetime(2025, 1, 15, 12, 0, 0, tzinfo=pytz.UTC) dt_naive = ensure_naive_datetime(dt_aware)
assert dt_naive.tzinfo is None assert dt_naive.year == 2025 assert dt_naive.month == 1 assert dt_naive.day == 15 assert dt_naive.hour == 12
def test_ensure_naive_datetime_with_est(self): """Test ensure_naive_datetime with EST timezone (should convert to UTC first).""" est = pytz.timezone('US/Eastern') # EST is UTC-5, so 12:00 EST = 17:00 UTC dt_aware = est.localize(datetime(2025, 1, 15, 12, 0, 0)) dt_naive = ensure_naive_datetime(dt_aware)
assert dt_naive.tzinfo is None # Should be converted to UTC time assert dt_naive.hour == 17 # 12:00 EST + 5 hours = 17:00 UTC
def test_ensure_naive_datetime_with_naive(self): """Test ensure_naive_datetime with already naive datetime.""" dt_naive = datetime(2025, 1, 15, 12, 0, 0) result = ensure_naive_datetime(dt_naive)
assert result.tzinfo is None assert result == dt_naive
def test_ensure_naive_datetime_with_none(self): """Test ensure_naive_datetime with None input.""" result = ensure_naive_datetime(None) assert result is None
def test_prepare_datetime_for_db_realistic_frontend_data(self): """Test prepare_datetime_for_db with realistic frontend datetime.""" # Simulate frontend sending UTC datetime with timezone info frontend_dt = datetime(2025, 1, 15, 12, 0, 0, tzinfo=pytz.UTC) db_dt = prepare_datetime_for_db(frontend_dt)
assert db_dt.tzinfo is None assert db_dt.year == 2025 assert db_dt.month == 1 assert db_dt.day == 15 assert db_dt.hour == 12
def test_prepare_datetime_for_db_with_none(self): """Test prepare_datetime_for_db with None input.""" result = prepare_datetime_for_db(None) assert result is None
class TestTimezoneIntegration: """Integration tests for timezone handling in realistic scenarios."""
def test_period_creation_with_timezone_aware_datetime(self): """Test that timezone-aware datetime from frontend works in period creation.""" from app.api.v1.endpoints.periods import PeriodCreate
# Simulate frontend sending timezone-aware datetime frontend_data = { "date": datetime(2025, 1, 15, 12, 0, 0, tzinfo=pytz.UTC), "ru_name": "2025 Янв", "start_date": datetime(2025, 1, 1, 0, 0, 0, tzinfo=pytz.UTC), "end_date": datetime(2025, 1, 31, 23, 59, 59, tzinfo=pytz.UTC) }
period_create = PeriodCreate(**frontend_data)
# All datetime fields should be timezone-naive after Pydantic validation assert period_create.date.tzinfo is None assert period_create.start_date.tzinfo is None assert period_create.end_date.tzinfo is None
# Values should be preserved assert period_create.date.year == 2025 assert period_create.date.month == 1 assert period_create.ru_name == "2025 Янв"
def test_period_update_with_mixed_timezone_data(self): """Test period update with mixed timezone-aware and naive datetime.""" from app.api.v1.endpoints.periods import PeriodUpdate
frontend_data = { "date": datetime(2025, 2, 15, 12, 0, 0, tzinfo=pytz.UTC), # timezone-aware "start_date": datetime(2025, 2, 1, 0, 0, 0), # timezone-naive "end_date": None # None value }
period_update = PeriodUpdate(**frontend_data)
# All should be properly handled assert period_update.date.tzinfo is None assert period_update.start_date.tzinfo is None assert period_update.end_date is None
